package main
import "fmt"
var lessThan20 = []string{"","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve","Thirteen","Fourteen","Fifteen","Sixteen","Seventeen","Eighteen","Nineteen"}
var tens = []string{"","Ten","Twenty","Thirty","Forty","Fifty","Sixty","Seventy","Eighty","Ninety"}
var thousands = []string{"","Thousand","Million","Billion"}
func convert(n int) string {
  if n == 0 { return "" }
  if n < 20 { return lessThan20[n] }
  if n < 100 {
    t := tens[n/10]
    r := convert(n%10)
    if r == "" { return t }
    return t + " " + r
  }
  h := lessThan20[n/100] + " Hundred"
  r := convert(n%100)
  if r == "" { return h }
  return h + " " + r
}
func numberToWords(num int) string {
  if num == 0 { return "Zero" }
  result := ""
  i := 0
  for num > 0 {
    chunk := num % 1000
    if chunk > 0 {
      cw := convert(chunk)
      mag := thousands[i]
      prefix := cw
      if mag != "" { prefix = cw + " " + mag }
      if result == "" { result = prefix } else { result = prefix + " " + result }
    }
    num /= 1000
    i++
  }
  return result
}
func main() {
  var n int
  fmt.Scan(&n)
  fmt.Println(numberToWords(n))
}
